// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        // The reference C is initialized with owner = msg.sender (this test contract).
        // After any sequence of calls, owner() should never be 0xdead.
        // The buggy version returns constant 0xdead in owner().
        // We call acceptOwnership() only to potentially trigger the buggy path.
        vm.assume(caller != address(0));
        vm.prank(caller);
        // acceptOwnership may revert if caller is not pendingOwner, but that's fine.
        // The rule: owner() must NOT be 0xdead.
        (bool success, ) = address(c).call(abi.encodeWithSignature("acceptOwnership()"));
        // The rule: owner() must not be 0xdead, regardless of whether acceptOwnership reverted.
        address ownerVal = c.owner();
        assertTrue(ownerVal != address(0xdead));
    }
}

